///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 주권조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    ins_combo_set(dts_LIST_STAT_CD, "ULDINS25600.xml", SCREN_PROCS_TP_CD_01, "00714", "ALL"); // 상장상태코드
    ins_combo_set(dts_BENFCERT_KIND_CD, "ULDINS25600.xml", SCREN_PROCS_TP_CD_01, "03431", "ALL"); // 수익증권종류

};

/**
